@use 'mixins' as *;

:host { display: block; }

.ftr {
  position: relative;
  padding-block: clamp(3rem, 6vw, 4.5rem) 2rem;
  border-top: 1px solid var(--hair);
  background: rgba(3, 5, 12, 0.5);
  backdrop-filter: blur(10px);
}

.ftr__top {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr);
  gap: clamp(2rem, 5vw, 4rem);
  padding-bottom: 2.5rem;

  @include upto($bp-md) { grid-template-columns: 1fr; }
}

/* --- Brand --- */
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 1rem;
  @include focus-ring;
}

.brand__mark {
  width: 32px;
  height: 32px;
  filter: drop-shadow(0 5px 12px rgba(60, 100, 220, 0.5));
}

.brand__text {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.98rem;
  letter-spacing: -0.03em;
  color: var(--ink);

  span { font-weight: 300; color: var(--ink-3); }
}

.ftr__blurb {
  font-size: 0.88rem;
  color: var(--ink-3);
  max-width: 26rem;
  margin-bottom: 1.4rem;
  line-height: 1.6;
}

.ftr__cta { font-size: 0.85rem; padding: 0.7rem 1.25rem; }

/* --- Link columns --- */
.ftr__cols {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;

  @include upto($bp-sm) { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

.ftr__col {
  h3 {
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--ink-4);
    margin-bottom: 0.9rem;
  }

  ul { list-style: none; display: grid; gap: 0.55rem; }

  a,
  span {
    font-size: 0.87rem;
    color: var(--ink-3);
  }

  a {
    position: relative;
    transition: color 0.3s var(--ease-out);
    @include focus-ring;

    /* underline that wipes in from the left */
    &::after {
      content: '';
      position: absolute;
      left: 0;
      bottom: -2px;
      width: 100%;
      height: 1px;
      background: currentColor;
      scale: 0 1;
      transform-origin: left center;
      transition: scale 0.35s var(--ease-out);
    }

    &:hover {
      color: var(--ink);
      &::after { scale: 1 1; }
    }
  }
}

/* --- Bottom bar --- */
.ftr__bottom {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  padding-top: 1.5rem;
  font-size: 0.78rem;
  color: var(--ink-4);
}

.ftr__made { opacity: 0.8; }

